#!/usr/bin/env python3
"""Offline SIP identity boundary processor (identity boundary protocol, rev. 1)."""

import json
import re
import sys


ANONYMOUS = "sip:anonymous@anonymous.invalid"
WS = " \t"
TOKEN = r"[A-Za-z0-9.!%*_+`'~\-]"
HEADER = re.compile(r"(" + TOKEN + r"+)[ \t]*:(.*)")
DISPLAY = re.compile(TOKEN + r"+(?:[ \t]+" + TOKEN + r"+)*")
TAG = re.compile(r"[ \t]*;[ \t]*tag[ \t]*=[ \t]*(" + TOKEN + r"{1,128})[ \t]*", re.I)
BAD_HEADER_CHAR = re.compile(r"[^\t\x20-\x7e]")
BAD_BODY_CHAR = re.compile(r"[^\t\r\n\x20-\x7e]")
SIP_USER = re.compile(r"(?:[A-Za-z0-9_.!~*'()+\-]|%[0-9A-Fa-f]{2})+")
USER_CHARACTERS = frozenset("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_.!~*'()+")
ESCAPE = re.compile(r"%([0-9A-Fa-f]{2})")
DNS_LABEL = re.compile(r"[A-Za-z0-9](?:[A-Za-z0-9\-]{0,61}[A-Za-z0-9])?")
TEL_NUMBER = re.compile(r"\+[1-9][0-9]{0,14}")
CALL_ID = re.compile(r"[A-Za-z0-9_.@+\-]{1,128}")
CSEQ = re.compile(r"([0-9]+)[ \t]+(INVITE|MESSAGE)")
DECIMAL = re.compile(r"[0-9]+")
COMPACT = {"f": "from", "t": "to", "i": "call-id", "l": "content-length", "c": "content-type"}
REQUIRED = frozenset(("from", "to", "call-id", "cseq", "content-length"))
SINGLETONS = REQUIRED | frozenset(("p-preferred-identity", "remote-party-id", "privacy", "content-type"))
RETAIN = SINGLETONS | frozenset(("p-asserted-identity",))


class InvalidRequest(Exception):
    """A framing, cardinality, or grammar error in the untrusted request."""


def unescape_user(match):
    ch = chr(int(match.group(1), 16))
    if ch not in USER_CHARACTERS:
        raise InvalidRequest
    return ch


def uri(text, sip_only=False):
    """Validate a URI and return its lexical normal form, without lookup."""
    scheme = text[:4].lower()
    if scheme == "sip:":
        user, at, host = text[4:].partition("@")
        if not at or not SIP_USER.fullmatch(user):
            raise InvalidRequest
        if "%" in user:
            user = ESCAPE.sub(unescape_user, user)
        if host.endswith("."):
            host = host[:-1]
        if not 1 <= len(host) <= 253:
            raise InvalidRequest
        if any(not DNS_LABEL.fullmatch(label) for label in host.split(".")):
            raise InvalidRequest
        return "sip:" + user + "@" + host.lower()
    if not sip_only and scheme == "tel:" and TEL_NUMBER.fullmatch(text[4:]):
        return "tel:" + text[4:]
    raise InvalidRequest


def quoted_end(text):
    """Index immediately after a leading quoted display name."""
    i = 1
    while i < len(text):
        c = text[i]
        if c == "\\":
            # Header character validation has already restricted this to printable
            # ASCII or HTAB.  A final backslash cannot escape a character.
            if i + 1 == len(text):
                raise InvalidRequest
            i += 2
        elif c == '"':
            return i + 1
        else:
            i += 1
    raise InvalidRequest


def address(text, tags=False, anonymous=False):
    """One address, optionally followed by the sole supported header parameter."""
    text = text.strip(WS)
    if not text:
        raise InvalidRequest

    if text[0] == '"':
        left = quoted_end(text)
        while left < len(text) and text[left] in WS:
            left += 1
        if left == len(text) or text[left] != "<":
            raise InvalidRequest
    else:
        left = text.find("<")
        if left != -1:
            display = text[:left].strip(WS)
            if display and not DISPLAY.fullmatch(display):
                raise InvalidRequest

    if left != -1:
        right = text.find(">", left + 1)
        if right == -1:
            raise InvalidRequest
        value = text[left + 1:right].strip(WS)
        suffix = text[right + 1:]
    else:
        semi = text.find(";")
        if semi == -1:
            value, suffix = text, ""
        else:
            value, suffix = text[:semi].strip(WS), text[semi:]

    normalized = uri(value)
    if normalized == ANONYMOUS and not anonymous:
        raise InvalidRequest
    tag = None
    if suffix.strip(WS):
        match = TAG.fullmatch(suffix) if tags else None
        if match is None:
            raise InvalidRequest
        tag = match.group(1)
    return normalized, tag


def asserted_addresses(text):
    """Split a PAI field only at commas outside quotes and angle brackets."""
    start = 0
    quoted = False
    angled = False
    escaped = False
    members = []
    for i, ch in enumerate(text):
        if quoted:
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == '"':
                quoted = False
        elif ch == '"':
            quoted = True
        elif ch == "<":
            if angled:
                raise InvalidRequest
            angled = True
        elif ch == ">":
            if not angled:
                raise InvalidRequest
            angled = False
        elif ch == "," and not angled:
            members.append(address(text[start:i])[0])
            if len(members) > 2:
                raise InvalidRequest
            start = i + 1
    if quoted or angled:
        raise InvalidRequest
    members.append(address(text[start:])[0])
    return members


def parse_request(raw):
    if len(raw) > 32768:
        raise InvalidRequest
    head, separator, body = raw.partition("\r\n\r\n")
    if not separator:
        raise InvalidRequest
    lines = head.split("\r\n")
    if len(lines) - 1 > 512:
        raise InvalidRequest
    if any(BAD_HEADER_CHAR.search(line) for line in lines) or BAD_BODY_CHAR.search(body):
        raise InvalidRequest

    request_line = lines[0].split(" ")
    if len(request_line) != 3 or request_line[0] not in ("INVITE", "MESSAGE") or request_line[2] != "SIP/2.0":
        raise InvalidRequest
    method = request_line[0]
    target = uri(request_line[1], sip_only=True)

    # Each list of chunks is one field; joining with SP implements unfolding
    # without prematurely stripping whitespace from any physical line.
    fields = []
    for line in lines[1:]:
        if line.startswith((" ", "\t")):
            if not fields:
                raise InvalidRequest
            fields[-1][1].append(line.lstrip(WS))
        else:
            match = HEADER.fullmatch(line)
            if match is None:
                raise InvalidRequest
            name = match.group(1).lower()
            name = COMPACT.get(name, name)
            fields.append((name, [match.group(2)]))
            if len(fields) > 128:
                raise InvalidRequest

    headers = {}
    pai_fields = []
    for name, chunks in fields:
        if name not in RETAIN:
            continue
        value = " ".join(chunks).strip(WS)
        if name == "p-asserted-identity":
            pai_fields.append(value)
        else:
            if name in headers:
                raise InvalidRequest
            headers[name] = value
    if not REQUIRED.issubset(headers):
        raise InvalidRequest

    from_uri, from_tag = address(headers["from"], tags=True, anonymous=True)
    to_uri, to_tag = address(headers["to"], tags=True, anonymous=True)
    call_id = headers["call-id"]
    if not CALL_ID.fullmatch(call_id):
        raise InvalidRequest
    match = CSEQ.fullmatch(headers["cseq"])
    if match is None or match.group(2) != method:
        raise InvalidRequest
    # Avoid Python's integer conversion length limit: arbitrarily many leading
    # zeroes are legal, even though the significant number has a small bound.
    sequence = match.group(1).lstrip("0")
    if not sequence or len(sequence) > 10 or (len(sequence) == 10 and sequence > "2147483647"):
        raise InvalidRequest
    length = headers["content-length"]
    if not DECIMAL.fullmatch(length) or (length.lstrip("0") or "0") != str(len(body)):
        raise InvalidRequest
    content_type = headers.get("content-type")
    if content_type is not None and not content_type:
        raise InvalidRequest
    privacy = headers.get("privacy", "none").lower()
    if privacy not in ("id", "none"):
        raise InvalidRequest

    ppi = None
    if "p-preferred-identity" in headers:
        ppi = address(headers["p-preferred-identity"])[0]
    rpid = None
    if "remote-party-id" in headers:
        rpid = address(headers["remote-party-id"])[0]
    pai = []
    for value in pai_fields:
        pai.extend(asserted_addresses(value))
        if len(pai) > 2:
            raise InvalidRequest
    if len(pai) == 2 and pai[0][:4] == pai[1][:4]:
        raise InvalidRequest

    return {
        "method": method, "target": target,
        "from": from_uri, "from_tag": from_tag,
        "to": to_uri, "to_tag": to_tag,
        "call_id": call_id, "sequence": sequence,
        "content_type": content_type, "body": body,
        "private": from_uri == ANONYMOUS or privacy == "id",
        "ppi": ppi, "rpid": rpid, "pai": pai,
    }


def reject(reason):
    return {"status": "reject", "reason": reason}


def forward(request, identity, trusted_out):
    from_uri = ANONYMOUS if request["private"] else identity
    from_value = "<" + from_uri + ">"
    if request["from_tag"] is not None:
        from_value += ";tag=" + request["from_tag"]
    to_value = "<" + request["to"] + ">"
    if request["to_tag"] is not None:
        to_value += ";tag=" + request["to_tag"]
    lines = [
        request["method"] + " " + request["target"] + " SIP/2.0",
        "From: " + from_value,
        "To: " + to_value,
        "Call-ID: " + request["call_id"],
        "CSeq: " + request["sequence"] + " " + request["method"],
        "Privacy: " + ("id" if request["private"] else "none"),
    ]
    if not request["private"] or trusted_out:
        lines.append("P-Asserted-Identity: <" + identity + ">")
    if request["content_type"] is not None:
        lines.append("Content-Type: " + request["content_type"])
    lines.append("Content-Length: " + str(len(request["body"])))
    return "\r\n".join(lines) + "\r\n\r\n" + request["body"]


def process(batch):
    aliases = {}
    domains = {}
    for identity, names in batch["directory"].items():
        aliases[identity] = identity
        for name in names:
            aliases[name] = identity
        domains[identity] = identity.rsplit("@", 1)[1]
    accounts = {}
    for subject, account in batch["accounts"].items():
        accounts[subject] = (account["primary"], set(account["allow"]) | {account["primary"]})
    gateways = {}
    for name, gateway in batch["gateways"].items():
        gateways[name] = (
            set(gateway["local_domains"]),
            {peer: set(authority) for peer, authority in gateway["peers"].items()},
        )

    results = []
    for job in batch["jobs"]:
        if "source" in job:
            previous = results[job["source"]]
            if previous["status"] != "accept":
                results.append(reject("upstream"))
                continue
            raw = previous["wire"]
        else:
            raw = job["raw"]
        try:
            request = parse_request(raw)
        except InvalidRequest:
            results.append(reject("syntax"))
            continue

        local_domains, peers = gateways[job["gateway"]]
        ingress = job["ingress"]
        basis = ingress["kind"]
        selected = None
        if basis == "local":
            account = accounts.get(ingress["subject"])
            if account is None:
                results.append(reject("unauthenticated"))
                continue
            primary, allowed = account
            from_identity = None
            if request["from"] != ANONYMOUS:
                from_identity = aliases.get(request["from"])
                if from_identity not in allowed or domains.get(from_identity) not in local_domains:
                    results.append(reject("identity"))
                    continue
            if request["ppi"] is not None:
                selected = aliases.get(request["ppi"])
            elif from_identity is not None:
                selected = from_identity
            else:
                selected = primary
            if selected not in allowed or domains.get(selected) not in local_domains:
                results.append(reject("identity"))
                continue
        elif basis == "peer":
            authority = peers.get(ingress["name"])
            if authority is None or not request["pai"]:
                results.append(reject("unauthenticated"))
                continue
            selected = aliases.get(request["pai"][0])
            if selected is None or domains[selected] not in authority:
                results.append(reject("identity"))
                continue
            claims = list(request["pai"][1:])
            if request["from"] != ANONYMOUS:
                claims.append(request["from"])
            if request["ppi"] is not None:
                claims.append(request["ppi"])
            if request["rpid"] is not None:
                claims.append(request["rpid"])
            if any(aliases.get(claim) != selected for claim in claims):
                results.append(reject("identity"))
                continue
        else:
            results.append(reject("unauthenticated"))
            continue

        results.append({
            "status": "accept", "identity": selected, "basis": basis,
            "private": request["private"],
            "wire": forward(request, selected, job["trusted_out"]),
        })
    return {"results": results}


def main():
    batch = json.load(sys.stdin)
    json.dump(process(batch), sys.stdout, ensure_ascii=True, separators=(",", ":"))
    sys.stdout.write("\n")


if __name__ == "__main__":
    main()
